class Solution {
    public:int minimizeConcatenatedLength(vector<string>& words){
        const int INF=1000000000;
        vector dp(26,vector<int>(26,INF));
        dp[words[0].front()-'a'][words[0].back()-'a']=words[0].size();
        for(int index=1;index<(int)words.size();++index){
            int a=words[index].front()-'a',b=words[index].back()-'a',length=words[index].size();
            vector next(26,vector<int>(26,INF));
            for(int first=0;first<26;++first)for(int last=0;last<26;++last)if(dp[first][last]<INF){
                next[first][b]=min(next[first][b],dp[first][last]+length-(last==a));
                next[a][last]=min(next[a][last],dp[first][last]+length-(b==first));
            }
            dp=move(next);
        }
        int answer=INF;
        for(auto& row:dp)for(int value:row)answer=min(answer,value);
        return answer;
    }
};
